def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    from collections import deque
    from fractions import Fraction

    jump = dict(jumps)
    resolved = list(range(n + 1))

    for cell in jump:
        path = []
        current = cell
        while current in jump and resolved[current] == current:
            path.append(current)
            current = jump[current]
        destination = resolved[current]
        for node in path:
            resolved[node] = destination

    transitions = {}
    reachable = {0}
    queue = deque([0])

    while queue:
        cell = queue.popleft()
        if cell == n:
            continue

        destinations = []
        for roll in range(1, m + 1):
            landing = cell + roll
            if landing > n:
                landing = 2 * n - landing
            destination = resolved[landing]
            destinations.append(destination)
            if destination not in reachable:
                reachable.add(destination)
                queue.append(destination)
        transitions[cell] = destinations

    if n not in reachable:
        return None

    reverse = {cell: [] for cell in reachable}
    for cell, destinations in transitions.items():
        for destination in destinations:
            reverse[destination].append(cell)

    can_finish = {n}
    queue = deque([n])
    while queue:
        cell = queue.popleft()
        for previous in reverse[cell]:
            if previous not in can_finish:
                can_finish.add(previous)
                queue.append(previous)

    if len(can_finish) != len(reachable):
        return None

    states = sorted(reachable - {n})
    index = {cell: i for i, cell in enumerate(states)}
    size = len(states)
    matrix = [[0] * (size + 1) for _ in range(size)]

    for cell, i in index.items():
        matrix[i][i] = m
        matrix[i][size] = m
        for destination in transitions[cell]:
            if destination != n:
                matrix[i][index[destination]] -= 1

    previous_pivot = 1
    for k in range(size - 1):
        pivot = matrix[k][k]
        for i in range(k + 1, size):
            factor = matrix[i][k]
            for j in range(k + 1, size + 1):
                matrix[i][j] = (
                    matrix[i][j] * pivot - factor * matrix[k][j]
                ) // previous_pivot
            matrix[i][k] = 0
        previous_pivot = pivot

    solution = [Fraction(0) for _ in range(size)]
    for i in range(size - 1, -1, -1):
        value = Fraction(matrix[i][size])
        for j in range(i + 1, size):
            value -= matrix[i][j] * solution[j]
        solution[i] = value / matrix[i][i]

    answer = solution[index[0]]
    return [answer.numerator, answer.denominator]
